python3 - <<'EOF'
import hashlib, json, urllib.request

def audit(t):
    req = urllib.request.Request("http://127.0.0.1:8099/v1/audit", headers={"X-Tenant-ID": t})
    return json.load(urllib.request.urlopen(req))

def canon(v):
    return json.dumps(v, ensure_ascii=False, separators=(",", ":")).encode("utf-8")

for tenant in ("acme", "beta"):
    body = audit(tenant)
    prev = "0"*64
    for ev in body["events"]:
        seq, kind = ev[0], ev[1]
        assert ev[0]  # sanity
        assert ev[-2] == prev, f"{tenant} broken link at {seq}"
        if kind == "create":
            _,_,rid,kv,p,d = ev
            msg = [1, tenant, seq, "create", rid, kv, p]
        else:
            _,_,fv,tv,rw,p,d = ev
            msg = [1, tenant, seq, "rotate", fv, tv, rw, p]
        got = hashlib.sha256(canon(msg)).hexdigest()
        assert got == d, f"{tenant} bad digest at {seq}: {got} != {d}"
        prev = d
    print(tenant, "OK", len(body["events"]), "events")
EOF
